(function (all) { var mine = all["pt-BR"] = all["pt-BR"] || {}; var add = {"nav.skip":"Pular para o conteúdo","nav.site":"Site","nav.home":"Início","nav.features":"Recursos","nav.documentation":"Documentação","nav.changelog":"Registro de alterações","nav.language":"Idioma","hero.tagline":"Grave e transmita como um estúdio — cenas, fontes, multistream, um app limpo só.","hero.sub":"Um estúdio de transmissão ao vivo e gravação para Windows, macOS e Linux. Sem contas, sem telemetria e sem nenhum serviço de nuvem nosso: sua transmissão vai direto para as plataformas que você escolher.","notice.price":"O Freally Capture é gratuito hoje, mas pode não ser gratuito para sempre: versões futuras poderão ser vendidas.","hero.chipDesktop":"App para desktop","hero.noDownloads":"A versão 1.2.1 é a versão atual. Não há downloads neste site, e o código-fonte é privado.","what.title":"O que é","what.p1":"Entrar ao vivo costuma exigir um app para capturar, outro para mixar o som, um serviço para enviar a transmissão a várias plataformas e uma conta em cada um deles.","what.p2":"O Freally Capture é um único estúdio no seu próprio computador. Monte uma cena com sua tela, janelas, câmeras, mídias e sobreposições; componha-a na placa de vídeo; grave-a em até seis faixas de áudio; e transmita-a para várias plataformas ao mesmo tempo, direto da sua máquina, sem intermediários.","what.p3":"Ele não precisa de conta e não envia telemetria. O que sai do seu computador é a transmissão que você escolheu enviar, mais as poucas conexões que você mesmo ativa — cada uma descrita com clareza na documentação.","features.title":"O que tem nele","features.scenes.title":"Cenas na GPU","features.scenes.body":"Monte cenas com telas, janelas, jogos, câmeras, páginas da web, mídias, imagens e texto, e componha tudo ao vivo na placa de vídeo com filtros e transições.","features.multistream.title":"Multistream, direto","features.multistream.body":"Entre ao vivo na Twitch, no YouTube, na Kick, no Facebook, na Trovo ou num servidor seu — em vários ao mesmo tempo — por RTMP, RTMPS, SRT ou WHIP, direto da sua máquina.","features.record.title":"Gravação multifaixa","features.record.body":"Grave com o codificador de hardware da sua placa de vídeo ou sem perdas no formato próprio do Capture, em até seis faixas de áudio, com divisão de arquivos, marcadores de capítulo e arquivos à prova de travamentos.","features.audio.title":"Uma mesa de transmissão","features.audio.body":"Cada fonte no seu próprio canal, com redução de ruído, noise gate, compressor, equalizador e medição de loudness — tudo processamento de sinal clássico, sem IA em lugar nenhum.","features.safety.title":"Modo Estúdio e segurança","features.safety.body":"Prepare as mudanças na prévia antes que entrem no ar, confira tudo com uma checagem antes da live e mantenha à mão alarmes, troca automática de codificador e um botão de pânico.","features.guests.title":"Convidados remotos","features.guests.body":"Convide até oito convidados com um link. Eles entram por um navegador, e a câmera e o microfone deles chegam direto até você, ponto a ponto.","features.deep.title":"Câmera virtual, fonte de navegador, captura de jogos","features.deep.body":"Seu programa como webcam para videochamadas, qualquer página da web como fonte e jogos em tela cheia exclusiva — primeiro no Windows, com cada limitação informada.","features.free.title":"Gratuito hoje, local, sem IA","features.free.body":"Sem plano pago, sem conta, sem telemetria e sem modelo. Suas cenas, gravações e chaves de transmissão ficam no seu computador.","ladder.title":"Versão por versão","ladder.intro":"Todas as versões do Freally Capture até agora, da base à versão atual. O registro de alterações traz os detalhes de cada uma.","ladder.version":"Versão","ladder.state":"Estado","ladder.lands":"O que trouxe","ladder.state.done":"Pronto","ladder.rung.v0.10.0":"A base: a interface do app para desktop sobre o seu próprio motor, as verificações de build no Windows, no macOS e no Linux, e este site.","ladder.rung.v0.25.0":"Captura: telas, janelas e webcams no Windows, no macOS e no Linux, ao vivo na prévia.","ladder.rung.v0.40.0":"O compositor na GPU: cenas montadas a partir de fontes e compostas na placa de vídeo, com filtros como chroma key, correção de cor, LUTs e desfoque.","ladder.rung.v0.55.0":"Áudio e gravação: um mixer com até seis faixas e filtros de DSP clássico, e gravação multifaixa com codificadores de hardware e o formato sem perdas próprio do Capture.","ladder.rung.v0.56.0":"Uma prévia nativa na GPU: o programa desenhado direto do compositor, sem atraso.","ladder.rung.v0.70.0":"O estúdio: transmissão para Twitch, YouTube, Kick, Facebook e Trovo com reconexão automática, Modo Estúdio com transições, atalhos de teclado, perfis e um painel de estatísticas.","ladder.rung.v0.85.0":"Transmissão a fundo: multistream para várias plataformas ao mesmo tempo, SRT e WHIP, uma tela vertical, cenas aninhadas, um buffer de replay e uma sobreposição de chat que não pede login.","ladder.rung.v0.90.0":"Controle remoto e extensões: uma API WebSocket protegida por senha, painéis de navegador, scripts Lua em sandbox e um SDK de plugins, tudo local e desligado por padrão.","ladder.rung.v0.95.0":"Distribuição: um atualizador automático assinado, áudio capturado por aplicativo e o contrato de licença na primeira execução.","ladder.rung.v0.96.0":"Um estúdio para todos: 18 idiomas, suporte completo a teclado e leitores de tela, um assistente de configuração inicial, uma paleta de comandos e temas.","ladder.rung.v0.97.0":"Criação e monitoramento de cenas: desfazer e refazer, um importador de coleções de cenas do OBS, guias de alinhamento, uma bancada de chroma key, uma multivisualização e projetores.","ladder.rung.v0.98.0":"Segurança no ar: uma checagem antes da live, alarmes, um painel de saúde das fontes, troca automática de codificador, gravação à prova de travamentos, um botão de pânico e uma proteção ao sair.","ladder.rung.v0.99.0":"Fontes, dispositivos e calibração: sinais de teste, calibração de sincronia de áudio e vídeo, temporizadores e relógios, texto vindo de um arquivo, um mapa de atalhos, desentrelaçamento e controles de câmera.","ladder.rung.v0.200.0":"Automação e captura a fundo: regras, macros, controle por MIDI e OSC, um painel touch na rede local, luzes de tally, câmeras PTZ e um roteiro do programa, além de zoom de recorte e mapeamento de tons de HDR para SDR.","ladder.rung.v0.300.0":"Novas fontes e sobreposições: replay instantâneo, uma playlist sem pausas, um editor de títulos e placares, um visualizador de áudio, uma sobreposição de estatísticas, um cronômetro de splits, uma sobreposição de entradas, recepção pela rede local e Freally Link.","ladder.rung.v0.400.0":"O compositor a fundo: distorção 3D pelos cantos, keyers de saída, congelamento de quadro, mais desfoques, a transição de movimento, um estúdio de shaders WGSL, máscaras Bézier e stingers com track matte.","ladder.rung.v0.500.0":"Produção de áudio: roteamento de saídas, uma matriz de ducking, um automixer, normalização de loudness, um equalizador paramétrico, uma mesa de efeitos sonoros, gravação de podcast e detecção de plugins CLAP e VST3.","ladder.rung.v0.600.0":"Gravação e replay a fundo: gravação ISO por fonte, um cortador de clipes, gravação com transparência, marcadores automáticos, uma sequência de tarefas após a gravação, uma verificação de integridade e timecode SMPTE.","ladder.rung.v0.700.0":"Entendendo a transmissão: um simulador de rede, um modo de ensaio, uma linha do tempo de quadros perdidos, um relatório da sessão, um benchmark de codificadores e fontes que aparecem só na transmissão ou só na gravação.","ladder.rung.v0.800.0":"Convidados remotos e produção: até oito convidados, uma sala de espera, sinais, um painel de qualidade da conexão, um telestrador, um teleprompter e grades automáticas de convidados.","ladder.rung.v0.900.0":"Gestão do estúdio: pacotes de cenas, comparar e mesclar, snapshots com nome, modo portátil, backups num único arquivo, um editor de temas e layouts de painéis.","ladder.rung.v0.910.0":"O teleprompter, reformulado: marcas de pausa, uma contagem regressiva de início, ritmo em BPM, leitura em voz alta e preenchimento automático nos 18 idiomas.","ladder.rung.v1.0.0":"A primeira versão estável: todos os recursos planejados, mais uma contagem regressiva de “Começa em breve”, música de fundo, uma barra de redes sociais e um banner de mensagem de chat em destaque.","ladder.rung.v1.1.0":"Um MP4 fácil de compartilhar, gravado ao lado de cada gravação sem perdas quando ela termina.","ladder.rung.v1.2.0":"Captura avançada e a web: uma câmera virtual, uma fonte de navegador de verdade e captura de jogos, primeiro no Windows.","ladder.rung.v1.2.1":"A auditoria: nenhum recurso novo, uma revisão completa de segurança e correção, e as três novidades da 1.2.0 finalmente funcionando.","ladder.note":"Toda versão listada está pronta. O que vem depois da 1.2.1 é planejado em particular e aparece aqui quando for lançado. Nenhuma delas é um download neste site.","honest.title":"As coisas que a maioria dos sites coloca lá embaixo","honest.windows.title":"Alguns dos recursos mais novos são só para Windows","honest.windows.body":"Na 1.2.1, a câmera virtual, a captura de jogos e os efeitos de cursor funcionam só no Windows, e a fonte de navegador foi verificada primeiro no Windows. O resto do estúdio funciona no Windows, no macOS e no Linux.","honest.signed.title":"Dois componentes ainda não têm assinatura de código","honest.signed.body":"O componente de sistema da câmera virtual e o ambiente de execução da fonte de navegador ainda não têm assinatura de código, e faltam dois testes ao vivo: a câmera dentro de uma videochamada de verdade e a captura de jogos num jogo protegido. O registro de alterações diz isso na versão que os adicionou.","honest.network.title":"O que de fato vai para a internet","honest.network.body":"Suas transmissões vão para as plataformas que você configura. A negociação da conexão de uma sessão com convidados passa por um serviço de sinalização público; uma sobreposição de chat lê o chat público de um canal; o ffmpeg e o ambiente de execução do navegador são baixados na primeira vez que você precisa deles; o app procura atualizações; e um relatório de problema só é enviado quando você aperta Enviar na página dele. Tirando a busca por atualizações, cada uma dessas coisas só acontece porque você a configurou.","honest.downloads.title":"Não há downloads aqui","honest.downloads.body":"Este site descreve o Freally Capture; ele não o distribui. Não há página, link nem botão de download, e o código-fonte é privado.","footer.licence":"Proprietário — Todos os direitos reservados. © Mike Weaver. Gratuito para usar hoje; versões futuras poderão ser vendidas. Não é de código aberto.","footer.yours":"O que você grava e transmite é seu, e a responsabilidade por isso também. O autor do Freally Capture nunca recebe, guarda nem repassa nada disso.","featuresPage.title":"Tudo o que ele faz","featuresPage.lead":"Um estúdio de transmissão ao vivo e gravação no seu próprio computador: cenas compostas na placa de vídeo, gravação multifaixa e multistream para todas as plataformas ao mesmo tempo, direto da sua máquina.","featuresPage.version":"Esta página descreve o Freally Capture 1.2.1, a versão lançada: tudo o que está nela está na 1.2.1, e nada do que está planejado para depois aparece aqui.","featuresPage.numbers.title":"Em números","featuresPage.numbers.intro":"Cada número é o que a versão 1.2.1 faz, contado a partir do código e do registro de alterações. Nada foi arredondado para cima.","featuresPage.numbers.systems":"sistemas operacionais: Windows, macOS e Linux","featuresPage.numbers.protocols":"protocolos de transmissão: RTMP, RTMPS, SRT e WHIP","featuresPage.numbers.platforms":"plataformas integradas — Twitch, YouTube, Kick, Facebook e Trovo — mais qualquer servidor seu","featuresPage.numbers.tracks":"faixas de áudio numa gravação","featuresPage.numbers.encoders":"famílias de codificadores de hardware: NVENC, Quick Sync, AMF, VAAPI e VideoToolbox","featuresPage.numbers.guests":"convidados remotos numa sessão","featuresPage.numbers.languages":"idiomas","featuresPage.numbers.accounts":"contas para criar","featuresPage.numbers.ai":"modelos de IA","featuresPage.numbers.price":"preço hoje","featuresPage.free.title":"Gratuito hoje","featuresPage.free.body":"Tudo o que o Freally Capture faz hoje é gratuito, para todos: sem plano pago, sem assinatura, sem conta, sem marca d'água e sem período de teste que expira. O que você grava e transmite é seu.","featuresPage.cards.title":"O que a versão 1.2.1 faz","featuresPage.cards.scenes.title":"Cenas e fontes na GPU","featuresPage.cards.scenes.body":"Telas, janelas, jogos, webcams e placas de captura, páginas da web, mídias, playlists, imagens, texto, temporizadores e sinais de teste, compostos ao vivo na placa de vídeo. Cenas aninhadas, grupos, fontes compartilhadas, uma tela vertical 9:16 e desfazer para cada edição.","featuresPage.cards.effects.title":"Filtros e transições","featuresPage.cards.effects.body":"Chroma key, correção de cor, LUTs, máscaras, uma família de desfoques, inclinação 3D e seus próprios shaders WGSL, em cada fonte. Corte, fade, deslizar, stinger, cortina luma e uma transição de movimento que leva os itens de uma cena para a outra.","featuresPage.cards.studio.title":"Modo Estúdio e monitoramento","featuresPage.cards.studio.body":"Prepare o próximo plano na prévia e mande para o programa quando estiver pronto. Uma multivisualização, projetores em tela cheia em qualquer monitor, keyers de saída sobre todas as cenas e um painel de estatísticas com números reais.","featuresPage.cards.multistream.title":"Multistream, direto da sua máquina","featuresPage.cards.multistream.body":"Entre ao vivo em várias plataformas ao mesmo tempo por RTMP, RTMPS, SRT ou WHIP, sem serviço intermediário no meio. Cada destino se reconecta sozinho, então se um falhar ele nunca derruba os outros.","featuresPage.cards.recording.title":"Gravações que resistem","featuresPage.cards.recording.body":"Codificadores de hardware, com o x264 como reserva, para MP4, MKV, MOV ou WebM, ou no formato sem perdas próprio do Capture; até seis faixas de áudio; um arquivo limpo para cada fonte; gravações que sobrevivem a um travamento, e um reparo na próxima abertura.","featuresPage.cards.audio.title":"Uma mesa de áudio de transmissão","featuresPage.cards.audio.body":"Redução de ruído, noise gate, compressor, limitador, equalizador paramétrico e de-esser em cada canal, com ducking, um automixer, normalização de loudness, uma mesa de efeitos sonoros e gravação de podcast. Processamento de sinal clássico, sem IA.","featuresPage.cards.replay.title":"Replay instantâneo","featuresPage.cards.replay.body":"Um buffer de replay contínuo que guarda os últimos momentos com uma tecla, e uma fonte de replay que os devolve ao programa em velocidade normal, à metade ou a um quarto. Um cortador de clipes exporta sem recodificar quando possível.","featuresPage.cards.guests.title":"Convidados pelo navegador","featuresPage.cards.guests.body":"Até oito convidados entram por um link, num navegador, sem instalar nada. Uma sala de espera, sinais privados, a conexão de cada convidado num relance e uma grade automática com crachás de nome.","featuresPage.cards.safety.title":"Segurança no ar","featuresPage.cards.safety.body":"Uma checagem antes da live, alarmes para silêncio, clipping, imagem congelada e disco enchendo, troca de codificador no meio da transmissão, um botão de pânico, um modo de ensaio que não envia nada e um encerramento que finaliza tudo na ordem certa.","featuresPage.cards.automation.title":"Automação e controle","featuresPage.cards.automation.body":"Regras, macros e variáveis; controladores MIDI e OSC; um painel touch e luzes de tally no seu celular; câmeras PTZ; um roteiro do programa; uma API WebSocket para o Stream Deck; scripts Lua e plugins. Tudo desligado por padrão.","featuresPage.cards.deep.title":"Câmera virtual, fonte de navegador, captura de jogos","featuresPage.cards.deep.body":"Seu programa como webcam para apps de videochamada; qualquer página da web renderizada como fonte; e jogos em tela cheia exclusiva por meio de um hook que você aprova jogo a jogo. Primeiro no Windows, com as limitações informadas abaixo.","featuresPage.cards.private.title":"Local, privado, sem IA","featuresPage.cards.private.body":"Sem conta, sem telemetria e sem nenhum serviço de nuvem nosso. Suas gravações e chaves de transmissão ficam no seu computador, e nenhum filtro usa um modelo: todos são processamento de sinal clássico.","featuresPage.compare.title":"Lado a lado com os estúdios comerciais","featuresPage.compare.intro":"O Freally Capture ao lado dos estúdios comerciais usados para transmitir e gravar. A coluna do Capture é a versão lançada, a 1.2.1. Cada célula de outro produto vem das páginas do próprio fabricante, verificadas em 2 de outubro de 2026, e os preços são os preços de tabela nos EUA em outubro de 2026.","featuresPage.compare.legend.yes":"tem","featuresPage.compare.legend.partly":"em parte","featuresPage.compare.legend.no":"não tem","featuresPage.compare.legend.unknown":"não verificado","featuresPage.compare.feature":"Recurso","featuresPage.compare.row.price":"Preço (USD, outubro de 2026)","featuresPage.compare.freeToday":"Gratuito hoje","featuresPage.compare.price.streamlabs":"US$ 27 por mês ou US$ 189 por ano","featuresPage.compare.price.xsplit":"US$ 14,99 por mês, US$ 59,99 por ano ou US$ 119,99 uma vez","featuresPage.compare.price.vmix":"US$ 1.200 uma vez","featuresPage.compare.price.wirecast":"US$ 79 por mês, ou US$ 504 por ano","featuresPage.compare.price.ecamm":"US$ 40 por mês ou US$ 384 por ano","featuresPage.compare.price.restream":"US$ 19 por mês ou US$ 190 por ano","featuresPage.compare.row.systems":"Funciona no Windows, no macOS e no Linux","featuresPage.compare.note.browser":"num navegador","featuresPage.compare.row.multistream":"Transmite para várias plataformas ao mesmo tempo","featuresPage.compare.note.channels3":"3 canais neste plano","featuresPage.compare.row.direct":"…direto do seu computador, sem serviço intermediário no meio","featuresPage.compare.note.servers":"pelos servidores do fabricante","featuresPage.compare.row.srt":"Saída SRT","featuresPage.compare.note.business":"a partir do plano Business","featuresPage.compare.row.whip":"Saída WHIP (WebRTC)","featuresPage.compare.note.customStream":"saída “Custom Stream”","featuresPage.compare.note.beta":"em beta","featuresPage.compare.row.vcam":"Uma câmera virtual para videochamadas","featuresPage.compare.note.windowsOnly":"só Windows, por enquanto","featuresPage.compare.row.guests":"Convidados entram por um navegador","featuresPage.compare.note.p2p":"até 8, ponto a ponto","featuresPage.compare.note.collab":"até 11 convidados ou câmeras","featuresPage.compare.note.vmixCall":"até 8, pelo vMix Call","featuresPage.compare.note.rendezvous":"até 7, pelo Rendezvous","featuresPage.compare.note.ecammGuests":"até 10 no Apple Silicon","featuresPage.compare.note.restreamGuests":"10 na tela, anfitrião incluído","featuresPage.compare.row.replay":"Replay instantâneo","featuresPage.compare.row.tracks":"Várias faixas de áudio numa gravação","featuresPage.compare.note.tracks6":"até 6 faixas","featuresPage.compare.note.tracks5":"5 faixas","featuresPage.compare.note.channels":"como canais, só AVI ou WAV","featuresPage.compare.note.tracks8":"até 8 faixas","featuresPage.compare.note.separateFiles":"como arquivos separados","featuresPage.compare.note.professional":"a partir do plano Professional","featuresPage.compare.row.account":"Funciona sem conta","featuresPage.compare.note.recordingOnly":"só para gravar","featuresPage.compare.note.licenceAccount":"licença vinculada a uma conta","featuresPage.compare.note.key":"uma chave de licença","featuresPage.compare.note.signIn":"exige login","featuresPage.compare.row.noAi":"Sem recursos de IA","featuresPage.compare.note.aiHighlights":"destaques de jogo com IA","featuresPage.compare.note.aiBackground":"remoção de fundo com IA","featuresPage.compare.note.aiClips":"clipes e música com IA","featuresPage.compare.summary":"O que o Freally Capture tem e os outros não: é o único app para desktop aqui que funciona no Linux além do Windows e do macOS, e o único gratuito. Quatro dos seis exigem conta e quatro têm recursos de IA; o Capture não tem nem uma coisa nem outra, e transmite para várias plataformas direto do seu computador, enquanto o Streamlabs e o Restream fazem sua transmissão passar pelos próprios servidores.","featuresPage.compare.theyWin":"Onde eles ganham: o Wirecast Pro grava até 8 faixas de áudio, contra 6 do Capture, e o Streamlabs Ultra aceita até 11 convidados ou câmeras e o Ecamm até 10, contra 8 do Capture. Streamlabs, XSplit, vMix, Wirecast e Ecamm têm câmera virtual; a do Capture funciona só no Windows na 1.2.1 e ainda não tem assinatura de código.","featuresPage.compare.obs":"O OBS Studio também é gratuito e de código aberto, funciona nos três sistemas e tem SRT, WHIP, câmera virtual, buffer de replay e seis faixas de áudio. Para transmitir para várias plataformas ao mesmo tempo, ele precisa de um plugin de terceiros; no Capture isso vem integrado, assim como os convidados que entram pelo navegador.","featuresPage.compare.asOf":"O preço do Capture é o de hoje: ele é gratuito hoje, e versões futuras poderão ser vendidas. Os outros produtos também mudam; esta tabela vale para 2 de outubro de 2026.","featuresPage.why.title":"Por que ele é feito assim","featuresPage.why.local.title":"Fica no seu computador","featuresPage.why.local.body":"Uma ferramenta de transmissão nunca deveria virar “conecte seu canal”. Não há conta para criar nem intermediário nosso no meio: sua transmissão vai do seu computador para as plataformas que você escolheu.","featuresPage.why.owned.title":"Um motor próprio","featuresPage.why.owned.body":"O compositor, o motor de áudio e o formato de gravação sem perdas são do próprio Capture. Os codecs que as plataformas exigem vêm do ffmpeg, baixado na primeira vez que você precisa dele em vez de vir junto.","featuresPage.why.dsp.title":"Processamento de sinal clássico","featuresPage.why.dsp.body":"Redução de ruído, chroma key e mapeamento de tons são fórmulas, não modelos. A mesma entrada com os mesmos ajustes dá o mesmo resultado, e nada precisa ser baixado para que funcionem.","featuresPage.why.safe.title":"Desligado até você ligar","featuresPage.why.safe.body":"Toda escuta de rede, toda automação e toda captura arriscada vem desligada por padrão. A captura de jogos pede sua permissão para cada jogo, e uma coleção de cenas compartilhada nunca pode levar essa permissão junto.","featuresPage.why.honest.title":"Honesto sobre suas lacunas","featuresPage.why.honest.body":"Quando um recurso funciona em um só sistema, ainda não tem assinatura de código ou ainda deve um teste ao vivo, o app, o registro de alterações e esta página dizem isso.","featuresPage.limits.title":"O que a 1.2.1 não faz","featuresPage.limits.vcam":"A câmera virtual funciona só no Windows; as câmeras para macOS e Linux não estão nesta versão.","featuresPage.limits.game":"A captura de jogos funciona só no Windows e copia jogos Direct3D 11; jogos HDR e Direct3D 12 passam para a captura de janela.","featuresPage.limits.browser":"A fonte de navegador mostra a imagem de uma página, mas ainda não o som.","featuresPage.limits.signed":"O componente de sistema da câmera virtual e o ambiente de execução do navegador ainda não têm assinatura de código, e faltam dois testes ao vivo: a câmera dentro de uma videochamada de verdade e a captura de jogos num jogo protegido.","featuresPage.limits.cursor":"Os efeitos de cursor e a sobreposição de teclado e mouse funcionam só no Windows.","featuresPage.limits.ai":"Ele não tem recursos de IA — nada de remoção de fundo, legendas ou clipes de destaques com IA — e isso é de propósito.","featuresPage.limits.downloads":"Não há downloads neste site, nem nesta página.","docs.title":"Documentação","docs.intro":"Como usar o Freally Capture, versão 1.2.1: montar uma cena, gravá-la, entrar ao vivo e tudo o que há em volta. Cada seção diz em quais sistemas um recurso funciona quando não são os três.","search.placeholder":"Pesquisar na documentação","docs.contents":"Sumário","join.title":"Entrar como convidado remoto","join.button.join":"Entrar com câmera e microfone","join.button.leave":"Sair","join.greenRoom":"Você está na sala de espera — o anfitrião está conferindo sua câmera e seu microfone. Você entra no ar em instantes.","join.cue":"SINAL","join.selfLabel":"Você — é isto que o anfitrião recebe.","join.hostSharing":"O anfitrião está compartilhando a visão dele.","join.fine":"Nada se conecta até você tocar em Entrar. Sua câmera e seu microfone vão direto para o anfitrião, ponto a ponto por WebRTC e criptografados no trajeto; só a negociação da conexão passa por um serviço de sinalização público. Esta página roda no seu navegador e não envia mais nada. O anfitrião pode ouvir você, colocar você no ar, silenciar ou remover você, e você faz parte de tudo o que ele gravar ou transmitir.","join.appPrompt":"Tem o Freally Capture instalado?","join.appLink":"Abrir este convite no app","join.status.checking":"Verificando seu convite…","join.seconds":"{{n}} s","join.hours":"{{n}} h","join.minutes":"{{n}} min","join.status.invited":"Você foi convidado. O convite vale por cerca de {{time}} — toque em Entrar quando estiver pronto.","join.status.expired":"Este convite expirou — peça um novo link ao anfitrião.","join.status.missing":"Este link não tem convite — abra exatamente o link ou o QR code que o anfitrião compartilhou.","join.status.damaged":"Este convite parece danificado — peça ao anfitrião para compartilhar o link de novo.","join.button.mutedByHost":"Silenciado pelo anfitrião","join.button.unmute":"Ativar meu microfone","join.button.mute":"Silenciar meu microfone","join.button.stopShare":"Parar de compartilhar","join.button.share":"Compartilhar minha tela","join.status.noReconnect":"Não foi possível reconectar — recarregue esta página enquanto seu convite ainda vale para entrar de novo.","join.status.reconnecting":"Conexão perdida — reconectando em {{seconds}} s (tentativa {{attempt}} de {{max}})…","join.status.requesting":"Pedindo acesso à sua câmera e ao seu microfone…","join.status.blocked":"Câmera ou microfone bloqueado: {{error}} — permita o acesso e toque em Entrar de novo.","join.status.reconnectedMuted":"Reconectado — seu microfone continua silenciado (você o silenciou).","join.status.calling":"Chamando o anfitrião…","join.status.hostMuted":"O anfitrião silenciou você.","join.status.hostUnmuted":"O anfitrião ativou seu microfone de novo.","join.status.removed":"O anfitrião removeu você — o link continua funcionando se você for convidado de novo.","join.status.banned":"O anfitrião removeu você desta sessão.","join.status.ended":"O anfitrião encerrou a sessão.","join.status.callError":"Erro na chamada: {{error}}","join.status.iceFailed":"A conexão direta falhou — os dois lados estão atrás de NATs restritivos. O anfitrião pode configurar um relay TURN na janela Remote dele.","join.status.unstable":"Conexão instável — tentando recuperar…","join.status.connected":"Conectado — compartilhando sua câmera e seu microfone. Mantenha esta página aberta.","join.status.signallingLost":"Sinalização perdida — reconectando (sua imagem e seu som continuam passando)…","join.status.hostUnreachable":"Não foi possível alcançar o anfitrião — a sessão dele ainda está aberta?","join.status.connectionError":"Erro de conexão: {{error}}","join.status.shareBlocked":"Compartilhamento de tela bloqueado: {{error}}","join.status.sharing":"Compartilhando sua tela na sessão.","join.status.left":"Você saiu da sessão."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
